{
  "bullets": [
    {
      "bullet": "Canada’s six largest banks account for 93 percent of system assets and remain highly capitalized and liquid, with non-performing loans remaining at low levels.",
      "section_ids": [
        "S07"
      ]
    },
    {
      "bullet": "Mortgage delinquency rates remain extremely low at 0.17 percent despite loan repricing, though arrears for auto and installment loans have risen above pre-pandemic levels.",
      "section_ids": [
        "S07"
      ]
    },
    {
      "bullet": "Nonbank financial institutions represent two-thirds of the financial system, but persistent data gaps preclude a definitive risk assessment regarding their leverage and illiquid investments.",
      "section_ids": [
        "S01",
        "S07"
      ]
    },
    {
      "bullet": "Under the baseline forecast, real GDP growth is projected to pick up to 1.3 percent in 2024, with inflation returning to the 2 percent target by early 2025.",
      "section_ids": [
        "S01",
        "S08"
      ]
    },
    {
      "bullet": "If high interest rates persist alongside rising unemployment above the 6 percent NAIRU, mortgage resets could generate elevated loan delinquencies and dent bank capitalization.",
      "section_ids": [
        "S07",
        "S08"
      ]
    },
    {
      "bullet": "Macroprudential measures have been tightened, including supervisory limits on originating mortgages with loan-to-income ratios exceeding 450 percent.",
      "section_ids": [
        "S07"
      ]
    },
    {
      "bullet": "General government gross debt is projected to fall from 107 percent of GDP at end-2023 to 95.25 percent of GDP by end-2029.",
      "section_ids": [
        "S08"
      ]
    },
    {
      "bullet": "Severe housing supply constraints pushed rental vacancy rates down to 1 percent while rent increases averaged 8 percent year-over-year in 2023.",
      "section_ids": [
        "S07"
      ]
    }
  ]
}

